import os
import hashlib
import time
from flask import Flask, request, jsonify, g
import psycopg2
from psycopg2 import sql

app = Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'appuser')
DB_PASS = os.environ.get('DB_PASS', 'secret')

def get_db():
    if 'db' not in g:
        g.db = psycopg2.connect(
            host=DB_HOST, dbname=DB_NAME,
            user=DB_USER, password=DB_PASS
        )
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def verify_session(session_token):
    """Verify session token against sessions table"""
    if not session_token:
        return None
    db = get_db()
    cur = db.cursor()
    cur.execute(
        "SELECT user_id, role FROM sessions WHERE token = %s AND expires_at > NOW()",
        (session_token,)
    )
    row = cur.fetchone()
    return {'user_id': row[0], 'role': row[1]} if row else None

@app.route('/api/reports/generate', methods=['POST'])
def generate_report():
    session = verify_session(request.headers.get('X-Session-Token'))
    if not session:
        return jsonify({'error': 'unauthorized'}), 401

    data = request.get_json()
    report_type = data.get('type', 'summary')
    date_from = data.get('date_from', '2024-01-01')
    date_to = data.get('date_to', '2024-12-31')
    department = data.get('department')

    db = get_db()
    cur = db.cursor()

    # Build report query based on type
    if report_type == 'detailed':
        base_query = "SELECT t.id, t.amount, t.description, t.created_at, u.email, u.full_name FROM transactions t JOIN users u ON t.user_id = u.id"
    else:
        base_query = "SELECT COUNT(*), SUM(t.amount), DATE(t.created_at) FROM transactions t JOIN users u ON t.user_id = u.id"

    # VULNERABLE: department parameter concatenated directly
    where_clause = f" WHERE t.created_at BETWEEN '{date_from}' AND '{date_to}'"
    if department:
        where_clause += f" AND u.department = '{department}'"

    if report_type != 'detailed':
        where_clause += " GROUP BY DATE(t.created_at)"

    full_query = base_query + where_clause

    try:
        cur.execute(full_query)
        rows = cur.fetchall()
    except Exception as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

    # Format results
    results = []
    for row in rows:
        results.append(list(row))

    # Log report generation for audit
    audit_hash = hashlib.sha256(f"{session['user_id']}:{time.time()}".encode()).hexdigest()[:16]
    cur.execute(
        "INSERT INTO audit_log (user_id, action, reference) VALUES (%s, %s, %s)",
        (session['user_id'], 'report_generated', audit_hash)
    )
    db.commit()

    return jsonify({
        'report_id': audit_hash,
        'type': report_type,
        'row_count': len(results),
        'data': results
    })

